@es = [0]
@os = [0]

def get_evens(i, j)
  @es[j+1] - @es[i]
end

def get_odds(i, j)
  @os[j+1] - @os[i]
end

def valid(ary, i, j)
  get_evens(i, j) == get_odds(i, j)
end

def get_key(i, b)
  "#{i},#{b}"
end

@cache = {}
def solve(i, ary, b)
  unless @cache[get_key(i, b)]
    if valid(ary, 0, i)==false
      @cache[get_key(i, b)] = -1
    elsif i<1
      @cache[get_key(i, b)] = 0
    else
      ans = 0
      ni = i-2
      while ni > 0 do
        cost = (ary[ni] - ary[ni+1]).abs
        if cost <= b && valid(ary, ni+1, i)
          mc = solve(ni, ary, b-cost)
          if mc != -1
            ans = [ans, mc+1].max
          end
        end
        ni -= 2
      end
      # puts [i, b, ans].inspect
      @cache[get_key(i, b)] = ans
    end
  end
  @cache[get_key(i, b)]
end

